from lib import *
S = SS('w16')
steps = [
    step("本机对 DF 的处理:UDP 设了 DF(IP_DONTFRAG,值 28)后发 1472 字节载荷(IP 总长 1500)成功,线上 1 个包、DF 位 1;发 1473 或 4000 字节载荷,内核当场报 [Errno 40] Message too long,线上 0 个包。不设 DF:1473 字节被分成 2 片(1500 + 21),4000 字节被分成 3 片(1500 / 1500 / 1068)。lo0 上 DF 置位发 20000 字节也是 Message too long(lo0 的 MTU 是 16384)。各协议默认的 DF:UDP 是 0,ping 默认是 0、ping -D 是 1,TCP 是 1。内核参数:path_mtu_discovery = 1,pmtud_blackhole_detection = 1,pmtud_blackhole_mss = 1200,mssdflt = 512;route get 显示默认路由和公网主机的 MTU 是 1500,127.0.0.1 是 16384。", t=tl(S(1)), mark=lidx(S(1), 'DF=置位 载荷 1473', 'DF=置位 载荷 4000', 'lo0(MTU 16384)'), done=lidx(S(1), 'DF=置位 载荷 1472', 'DF=不置位', 'DF 位 =', 'net.inet.tcp', 'route get'), kv=KV([['UDP 默认', 'DF = 0,放不下就分片'], ['TCP 默认', 'DF = 1,靠 PMTUD'], ['设了 DF 又太大', '本机直接 EMSGSIZE,不发包'], ['路由里的 MTU', 'en0 路径 1500,lo0 16384']], ['设了 DF 又太大'])),
    step("真实公网路径上的 DF 探测:DF=1 的 UDP 数据报发往三个公网主机没人监听的端口,每种大小 3 个。IP 总长 576、1000、1280、1400、1472、1480、1492 的探测,三个主机都全部得到“端口不可达”(包到了目的地);1500 字节的 9 个探测全部得到 ICMP 3/4(需要分片),报文里的“下一跳 MTU”字段是 1492,引用的原包总长 1500,回复来自私有地址的设备,回复包 TTL 62。也就是说这条路径上某处的链路 MTU 是 1492,比本机网口的 1500 小 8 字节,而发送方本机根本不知道——直到收到这个 ICMP。", t=tl(S(2)), mark=lidx(S(2), '1500     0+3/3', '收到的 3/4 报文里', '3/4 报文来自'), done=lidx(S(2), '共发出 72 个', '1492     3+0/3', '1472     3+0/3'), b=bars([['1492 字节 · 9 个探测到达', 9, '9 / 9'], ['1500 字节 · 9 个探测收到 3/4', 9, '9 / 9']], 9, mark=[1], done=[0]), kv=KV([['≤ 1492 字节', '全部到达目的地(端口不可达)'], ['1500 字节', '全部收到 ICMP 3/4'], ['3/4 里的下一跳 MTU', '1492'], ['本机网口 MTU', '1500,发送前无从得知']], ['3/4 里的下一跳 MTU'])),
    step("找出窄链路在第几跳:DF=1 的 1500 字节探测,TTL 1~3 得到的是超时(11/0),分别来自默认网关和两台私有地址的路由器;TTL 4~10 全部得到 3/4(下一跳 MTU 1492),每个 TTL 都 3/3。回 3/4 的设备和 TTL=3 回超时的是同一个地址(验证结果 True),回复包 TTL 都是 62。所以窄链路是第 3 跳路由器通往第 4 跳的那一段:TTL=4 的包要由第 3 跳转发过去,出口放不下,第 3 跳就丢包并回 3/4。注意它回的是路由器自己的出口 MTU,而不是整条路径的最小值——路径上后面还可能有更窄的。", t=tl(S(3)), mark=lidx(S(3), 'TTL= 4', 'TTL= 5', '从 TTL=4 起'), done=lidx(S(3), 'TTL= 1', 'TTL= 2', 'TTL= 3'), b=bars([['TTL=1~3 · 超时(11/0)', 3, '3 个 TTL'], ['TTL=4~10 · 需要分片(3/4)', 7, '7 个 TTL']], 7, mark=[1], done=[0]), kv=KV([['TTL=3', '第 3 跳超时 11/0'], ['TTL≥4', '第 3 跳回 3/4,下一跳 MTU 1492'], ['回复 TTL', '两者都是 62(同一台设备)'], ['3/4 的含义', '只说它自己的出口,不是整条路径']], ['TTL≥4'])),
    step("内核会记住吗:前面的探测已经让内核收到过很多 3/4,但 route get 公网主机的 MTU 仍是 1500,netstat -rn 里也没有这台主机的单独路由条目。再对同一目的地发 DF=1 的 UDP,IP 总长 1500、1492、1480 都“发送成功”——内核没有因此拒绝 1500 字节的包(它依然会被发出去、再被路由器回 3/4)。这个实验没有观察到 UDP 套接字因为 3/4 而更新本机路由缓存;TCP 会不会更新没有验证(这条路径上对方的 MSS 本来就小于 1492−40,触发不了)。", t=tl(S(4)), mark=lidx(S(4), '再对同一目的地发 DF=1、IP 总长 1500'), done=lidx(S(4), '前面第二、三节', '总长 1492', '总长 1480', 'netstat -rn'), kv=KV([['route get 公网主机', 'MTU 仍是 1500'], ['再发 1500 字节 DF', '内核照发(发送成功)'], ['UDP 与 3/4', '没观察到路由缓存更新'], ['TCP', '没有验证']], ['再发 1500 字节 DF'])),
    step("TCP 的 MSS 通告:本机 SYN 通告的 MSS 都是 1460(1500 − 40)。对方 SYN-ACK 通告的 MSS:主机 A、B 是 1400(对应 MTU ≈ 1440),主机 C 和 E 是 1452(对应 MTU ≈ 1492),主机 D 没有连通。MSS 1452 对应的 1492,和上一节 3/4 里的下一跳 MTU 数值相同;这里只看到数值吻合,是对方还是中间设备把 MSS 调成这样的,没有验证。MSS 只反映对方通告的上限,不能发现路径中间更窄的链路——那要靠 DF 加 ICMP 3/4(或黑洞检测)。", t=tl(S(5)), mark=lidx(S(5), '主机 C', '主机 E'), done=lidx(S(5), '主机 A', '主机 B', '主机 D', 'MSS 是对方'), b=bars([['本机 SYN 通告 MSS', 1460, '1460'], ['主机 C、E 的 MSS', 1452, '1452'], ['主机 A、B 的 MSS', 1400, '1400']], 1460, mark=[1], done=[0, 2]), kv=KV([['本机', 'MSS 1460(1500 − 40)'], ['主机 C、E', 'MSS 1452 → MTU ≈ 1492'], ['主机 A、B', 'MSS 1400 → MTU ≈ 1440']], ['主机 C、E'])),
    step("黑洞(模拟,不是实测):假设路径四跳 MTU 是 1500 / 1500 / 1400 / 1500,发送方用 DF 发 1500 字节。ICMP 能回到发送方时:第一个包被路由器丢弃并回 3/4(下一跳 MTU 1400),改用 1400 重发就送达,共 2 个包。如果 ICMP 被防火墙拦住,发送方永远收不到 3/4,1500 字节的包一律被静默丢弃,试了 12 次也没有成功——这就是 PMTUD 黑洞:小包(握手、小请求)能通,大包(大响应)卡死。如果发送方在连续 3 次无应答后退到 1200 字节(这是纸面推演:本机 pmtud_blackhole_mss 是 1200,macOS 实际的触发条件和阈值没有实测),第 4 个包就能送达。", t=tl(S(6)), mark=lidx(S(6), '黑洞', '一直失败'), done=lidx(S(6), 'ICMP 能回到发送方', '退到 1200', '纸面推演'), b=bars([['ICMP 可达 · 发包数', 2, '2'], ['ICMP 被拦 · 退到 1200', 4, '4'], ['ICMP 被拦 · 无退避(放弃时)', 12, '12,仍失败']], 12, mark=[2], done=[0, 1]), kv=KV([['有 ICMP 3/4', '2 个包就找到 1400'], ['ICMP 被拦', '1500 字节永远发不过去(黑洞)'], ['黑洞检测', '降到小 MSS 重试(此处是模拟)']], ['ICMP 被拦'])),
]
A = mkartw('w16', 16, '网络协议,PMTUD,路径MTU,DF,ICMP,分片,MSS,黑洞,真实验证,动画演示',
    '实测路径 MTU 发现:DF 置位的 1500 字节 UDP 在公网路径第 3 跳处得到 ICMP 3/4(下一跳 MTU 1492),≤1492 的全部到达;本机设了 DF 的超大包直接 EMSGSIZE;UDP 收到 3/4 后内核路由缓存没变;黑洞的后果用模拟说明。',
    '为什么 TCP 的包都带 DF?路上有链路比 1500 小,发送方怎么知道?ICMP 被防火墙拦掉会怎么样?这篇用 DF 置位的探测包在真实公网路径上找到一条 MTU 1492 的链路,再看内核有没有记住它,最后用推演说明“黑洞”。',
    [('1492', '真实公网路径上第 3 跳路由器在 ICMP 3/4 里告知的下一跳 MTU(本机网口是 1500)'), ('9 / 9', '1500 字节的 DF 探测全部收到 3/4;1492 字节及以下的全部到达目的地'), ('EMSGSIZE', '本机对设了 DF 又超过接口 MTU 的 UDP 数据报直接拒绝,线上 0 个包')],
    [('DF 的作用', '<p>DF 置位的包放不下就不能分片,路由器丢掉它并回 ICMP 3/4,里面带着自己出口的 MTU。TCP 默认带 DF,UDP 与 ping 默认不带;设了 DF 又超过本机接口 MTU 的数据报在本机就报 Message too long。</p>'),
     ('在公网上探测', '<p>用不同大小的 DF 探测发往三个公网主机,≤1492 的全部到达目的地,1500 的全部收到 3/4,下一跳 MTU 字段是 1492。</p>'),
     ('窄链路在第几跳', '<p>让 TTL 从 1 递增,TTL=4 起开始收到 3/4,而且回包设备就是 TTL=3 回超时的那一跳:窄链路在第 3 跳通往第 4 跳的出口。</p>'),
     ('内核的反应', '<p>实验里 UDP 套接字收到很多 3/4 以后,route get 里这台主机的 MTU 仍是 1500,再发 1500 字节的 DF 包仍然“发送成功”。TCP 的行为这里没有验证。</p>'),
     ('MSS 通告', '<p>对方在 SYN-ACK 里通告的 MSS(1400 或 1452)反映的是对方一侧的限制,不是整条路径的最小 MTU。</p>'),
     ('黑洞', '<p>如果 ICMP 3/4 被拦,带 DF 的大包会被静默丢弃,而小包照常通。模拟了三种情形:ICMP 可达时 2 个包找到 1400;ICMP 被拦则一直失败;若发送方连续无应答后退到 1200 则第 4 个包送达(这一项是推演,不是 macOS 的实测)。</p>')],
    steps,
    [ENV_W + '。第一节在 en0(MTU 1500)上抓包并读本机 sysctl;第二、三节是三个公网主机与一条真实公网路径上的 DF 探测(UDP 到没人监听的端口),路径上设备的地址不写出,只记类别;第四、五节是同一台机器上的观察;第六节是纸面模拟,不是实测',
     '没有验证:TCP 收到 3/4 后是否更新路由缓存与降低 MSS;macOS 的黑洞检测(pmtud_blackhole_detection)的触发条件、退避次数;PLPMTUD(RFC 4821)的探测机制;IPv6 的 PMTUD(路由器不分片,只有 Packet Too Big);ICMP 被拦时真实网络上的黑洞表现;路径上第 3 跳之后还有没有更窄的链路'],
    '路径 MTU 发现')
